const self = this;
const URL = 'http://embedding_api:8003/v1/embeddings';
const LOTE = 32;

async function chamar(textos, tipo) {
  const r = await self.helpers.httpRequest({
    method: 'POST',
    url: URL,
    headers: { 'Content-Type': 'application/json' },
    body: { input: textos, input_type: tipo },
    json: true,
  });
  return r.data.sort((a, b) => a.index - b.index).map((d) => d.embedding);
}

return {
  embedDocuments: async (textos) => {
    const out = [];
    for (let i = 0; i < textos.length; i += LOTE) {
      out.push(...(await chamar(textos.slice(i, i + LOTE), 'passage')));
    }
    return out;
  },
  embedQuery: async (texto) => (await chamar([texto], 'query'))[0],
};
